import type { RequestHandler } from 'express';

export const timing = (): RequestHandler => (req, res, next) => {
  const t0 = performance.now();                     // pre
  res.once('finish', () =>                          // post, after the response is flushed
    log.info(`${req.method} ${req.originalUrl} ${(performance.now() - t0).toFixed(1)}ms`));
  next();                                           // next middleware or route handler
};
app.use('/api', timing(), requireAuth);

